// Atelier plugin API 1.1, as of Atelier 1.0.0-beta.4.
// Generated by sdk/generate.mjs from docs/plugin-api.json. Do not edit by hand.
//
// In a plugin's main.js:   // @ts-check
// with a jsconfig.json that includes this file (atelier-mod new writes one), or:
//   /// <reference path="./atelier.d.ts" />

declare namespace Atelier {
  /** A permission a plugin may ask for in its manifest. */
  type Permission = "network" | "notifications" | "openURL" | "appearance" | "menuBar" | "liveActivities" | "scenes" | "panels";

  /** #RRGGBB hex or a named ink. "accent" follows the widget style. */
  type Color = "primary" | "secondary" | "tertiary" | "accent" | "red" | "orange" | "yellow" | "green" | "mint" | "teal" | "blue" | "indigo" | "purple" | "pink" | "gray" | `#${string}`;

  /** A value, or a Promise of one: callbacks may be async. */
  type Awaitable<T> = T | Promise<T>;

  /** The size a widget prefers on the board. */
  type WidgetSize = "small" | "medium" | "large";

  /** A widget for the board. Add it with the Plugin widget kind and choose it from the list. */
  interface WidgetSpec {
    /** Defaults to one made from the title. */
    id?: string;
    /** Shown above the content and in the picker. */
    title?: string;
    /**
     * The size it prefers.
     * @default "small"
     */
    size?: WidgetSize;
    /**
     * Seconds between runs of data and view, 5 to 86400.
     * @default 60
     */
    refresh?: number;
    /** Fetches or computes data. May be async. */
    data?: () => Awaitable<any>;
    /** Turns data into a view. If missing, data's result is drawn as the view. */
    view?: (data: any) => Awaitable<View>;
  }

  /** What atelier.widget returns. */
  interface WidgetHandle {
    /** The widget's id. */
    readonly id: string;
    /** Runs data and view again now, for example after a click elsewhere changed your state. */
    refresh: () => void;
  }

  /** A tile for the Atelier Dock. */
  interface TileSpec {
    /** Defaults to one made from the title. */
    id?: string;
    /** The tile's name under the pointer. */
    title?: string;
    /** An SF Symbol for the icon. */
    symbol?: string;
    /** Up to 12 characters drawn under or instead of the symbol: "24:59". */
    text?: string;
    /** A red badge of up to 4 characters; null hides it. */
    badge?: string | number | null;
    /** The tile's colour. */
    tint?: Color;
    /** 0 to 1: a ring around the tile. */
    progress?: number;
    /** Runs when the tile is clicked. */
    onClick?: () => Awaitable<void>;
    /**
     * Its right-click (and press-and-hold) menu, above Atelier's own items.
     * @since Atelier 1.0.0-beta.4
     */
    menu?: MenuEntry[];
    /**
     * What may be dropped on it. Files never are.
     * @since Atelier 1.0.0-beta.4
     */
    accepts?: Array<"url" | "text">;
    /**
     * Runs when a link or text it accepts is dropped on it.
     * @since Atelier 1.0.0-beta.4
     */
    onDrop?: (drop: Drop) => Awaitable<void>;
  }

  /** What atelier.dockTile returns. */
  interface TileHandle {
    /** The tile's id. */
    readonly id: string;
    /** Merges the changes into the tile and redraws it. Cheap: updating every second is fine. */
    update: (changes: Partial<TileSpec>) => void;
  }

  /** An entry in Atelier's Command palette. */
  interface CommandSpec {
    /** Defaults to one made from the title. */
    id?: string;
    /** What the palette shows. */
    title: string;
    /** Defaults to the plugin's name. */
    subtitle?: string;
    /** Shown beside the entry, like "ctrl+opt+p" or "cmd+shift+k": at least one of cmd, ctrl, opt; keys are one character, space, return, tab, escape or f1 to f20. Shown, not bound globally. */
    shortcut?: string;
    /** Runs when the command is chosen. */
    run: () => Awaitable<void>;
  }

  /** An action for a hot corner or edge in Atelier's Corners chapter. */
  interface CornerActionSpec {
    /** Defaults to one made from the title. */
    id?: string;
    /** Shown in the Corners picker. */
    title: string;
    /** An SF Symbol. */
    symbol?: string;
    /** Runs when the corner fires. */
    run: () => Awaitable<void>;
  }

  /** Options for atelier.on. */
  interface OnOptions {
    /**
     * For the timer event: seconds between events, 5 to 86400.
     * @default 60
     */
    interval?: number;
  }

  /** Options for atelier.http.get. */
  interface HttpOptions {
    /** Ordinary headers such as Authorization and Accept. Cookie, Host, Origin, Referer, Content-Length and Connection are dropped. */
    headers?: Record<string, string>;
  }

  /** A frozen response. ok is true for 200 to 299; other statuses still resolve, so check ok. */
  interface HttpResponse {
    /** The HTTP status. */
    readonly status: number;
    /** True for status 200 to 299. */
    readonly ok: boolean;
    /** The body as text. */
    readonly text: string;
    /** Response headers, lowercased. */
    readonly headers: Record<string, string>;
    /** Parses text as JSON. */
    json: () => any;
  }

  /** Options for atelier.prompt. */
  interface PromptOptions {
    /** A sentence under the title. */
    message?: string;
    /** Grey text in the empty field. */
    placeholder?: string;
    /**
     * Hides what is typed. Use it for tokens.
     * @default false
     */
    secure?: boolean;
  }

  /** A notification. */
  interface NotifySpec {
    /** Cut at 80 characters. */
    title: string;
    /** Cut at 240 characters. */
    body?: string;
  }

  /** Any theme keys from THEMES.md, without format, id, name or version. */
  type ThemePatch = Record<string, any>;

  /**
   * Options for atelier.http.post, put, patch and delete.
   * @since Atelier 1.0.0-beta.4
   */
  interface HttpSendOptions {
    /** As for get. Cookie, Host, Origin, Referer, Content-Length and Connection are dropped. */
    headers?: Record<string, string>;
    /** The body, as text. */
    body?: string;
    /** Any JSON value, sent with Content-Type: application/json unless you set one. */
    json?: any;
  }

  /**
   * What a button, toggle or menu item runs: a function, or an id registered with atelier.action.
   * @since Atelier 1.0.0-beta.4
   */
  type Action = string | ((payload?: any) => Awaitable<void>);

  /**
   * What a toggle's action receives.
   * @since Atelier 1.0.0-beta.4
   */
  interface ToggleChange {
    /** The toggle's new state. */
    on: boolean;
  }

  /**
   * A choice in a menu. Without an action it shows greyed out, which suits a status line.
   * @since Atelier 1.0.0-beta.4
   */
  interface MenuItem {
    /** Up to 80 characters. */
    title: string;
    /** An SF Symbol. */
    symbol?: string;
    /** Runs when the item is chosen. */
    action?: () => Awaitable<void>;
    /** Draws a check mark. */
    checked?: boolean;
    /**
     * False greys it out.
     * @default true
     */
    enabled?: boolean;
    /** One level of submenus, instead of an action. */
    submenu?: MenuEntry[];
  }

  /**
   * An item, or "separator" (or "-") for a line; any other text is refused. A menu holds at most 40 entries in all.
   * @since Atelier 1.0.0-beta.4
   */
  type MenuEntry = MenuItem | string;

  /**
   * What a tile's onDrop receives.
   * @since Atelier 1.0.0-beta.4
   */
  interface Drop {
    /** An http, https or mailto link, or text. */
    kind: "url" | "text";
    /** The link or text, at most 8 KB. */
    value: string;
  }

  /**
   * A row a palette provider or stack provider answers with.
   * @since Atelier 1.0.0-beta.4
   */
  interface ResultRow {
    /** Up to 120 characters. Rows without a title are skipped. */
    title: string;
    /** A second line. */
    subtitle?: string;
    /** An SF Symbol. */
    symbol?: string;
    /** A PNG or JPEG in the plugin folder, by relative path. */
    image?: string;
    /** Runs when the row is chosen. */
    action?: () => Awaitable<void>;
  }

  /**
   * Rows in the Command palette as the owner types.
   * @since Atelier 1.0.0-beta.4
   */
  interface PaletteProviderSpec {
    /** Defaults to one made from the title. */
    id?: string;
    /** The section title in the palette. */
    title: string;
    /** 1 to 12 characters, no spaces. With "gh", asked only for queries starting with "gh ", and given the rest. */
    prefix?: string;
    /** Up to 20 rows, within 1 s. Asked 120 ms after typing stops. */
    search: (query: string) => Awaitable<Array<ResultRow | string>>;
  }

  /**
   * An item in the menu bar, owned by Atelier.
   * @since Atelier 1.0.0-beta.4
   */
  interface MenuBarItemSpec {
    /** Defaults to one made from the title. */
    id?: string;
    /** Its tooltip and accessibility name. */
    title?: string;
    /** An SF Symbol. A symbol, a text or both. */
    symbol?: string;
    /** Up to 16 characters beside the symbol. */
    text?: string;
    /** The menu that opens on click. */
    menu?: MenuEntry[];
  }

  /**
   * What atelier.menuBarItem returns.
   * @since Atelier 1.0.0-beta.4
   */
  interface MenuBarHandle {
    /** The item's id. */
    readonly id: string;
    /** Merges the changes and redraws it, menu included. */
    update: (changes: Partial<MenuBarItemSpec>) => void;
    /** Takes it out of the menu bar. */
    remove: () => void;
  }

  /**
   * A stack on the Atelier Dock whose items come from the plugin.
   * @since Atelier 1.0.0-beta.4
   */
  interface StackProviderSpec {
    /** Defaults to one made from the title. */
    id?: string;
    /** The stack's name. */
    title: string;
    /**
     * An SF Symbol.
     * @default "square.stack.3d.up"
     */
    symbol?: string;
    /**
     * Seconds an answer is reused, 0 to 86400. 0 asks every time the stack opens.
     * @default 0
     */
    refresh?: number;
    /** Up to 60 rows, within 4 s. */
    items: () => Awaitable<Array<ResultRow | string>>;
  }

  /**
   * What atelier.stackProvider returns.
   * @since Atelier 1.0.0-beta.4
   */
  interface StackHandle {
    /** The stack's id. */
    readonly id: string;
    /** Makes the next opening ask again. */
    refresh: () => void;
  }

  /**
   * A small live pill under the menu bar.
   * @since Atelier 1.0.0-beta.4
   */
  interface LiveActivitySpec {
    /** Defaults to one made from the title. */
    id?: string;
    /** What is happening. */
    title: string;
    /**
     * An SF Symbol.
     * @default "bolt.fill"
     */
    symbol?: string;
    /** Up to 60 characters. With until and no text, it counts down. */
    text?: string;
    /** 0 to 1: a bar in tint. */
    progress?: number;
    /** The bar's colour. */
    tint?: Color;
    /** When it ends by itself: a Date, an ISO date or ms since 1970. */
    until?: Date | string | number;
    /** Runs when it is clicked. */
    onTap?: () => Awaitable<void>;
  }

  /**
   * What atelier.liveActivity returns.
   * @since Atelier 1.0.0-beta.4
   */
  interface LiveActivityHandle {
    /** The activity's id. */
    readonly id: string;
    /** Merges the changes and redraws it. */
    update: (changes: Partial<LiveActivitySpec>) => void;
    /** Removes it. */
    end: () => void;
  }

  /**
   * A small floating window showing the plugin's HTML, sealed off: no network, files from its folder only, no navigation.
   * @since Atelier 1.0.0-beta.4
   */
  interface PanelSpec {
    /** Defaults to one made from the title. The same id again replaces the page. */
    id?: string;
    /** The window's title. */
    title?: string;
    /**
     * 200 to 1200 points.
     * @default 420
     */
    width?: number;
    /**
     * 120 to 900 points.
     * @default 320
     */
    height?: number;
    /** The page, at most 512 KB. Inside it, window.atelier.post(message) and window.atelier.onMessage(fn). */
    html: string;
    /**
     * Whether the owner can resize it.
     * @default false
     */
    resizable?: boolean;
    /** Messages the page posts. They also arrive as the panelMessage event. */
    onMessage?: (message: any) => Awaitable<void>;
  }

  /**
   * What atelier.panel returns.
   * @since Atelier 1.0.0-beta.4
   */
  interface PanelHandle {
    /** The panel's id. */
    readonly id: string;
    /** Brings it up without taking focus from the app in front. */
    show: () => void;
    /** Hides it. */
    hide: () => void;
    /** Sends JSON (up to 64 KB) to the page's onMessage. */
    post: (message: any) => void;
  }

  /**
   * One of the owner's Scenes.
   * @since Atelier 1.0.0-beta.4
   */
  interface Scene {
    /** Its name, as atelier.scenes.apply takes it. */
    name: string;
  }

  /**
   * One setting in the manifest's settings list.
   * @since Atelier 1.0.0-beta.4
   */
  interface SettingSpec {
    /** Letters, digits, - _ or ., up to 64. */
    key: string;
    /** text (up to 1000 characters), secret (kept in the Keychain, never shown again), number (with min and max), toggle, choice (with options), color (#RRGGBB), hotkeyHint (a shortcut like cmd+shift+p, shown as a hint, not bound). */
    type: "text" | "secret" | "number" | "toggle" | "choice" | "color" | "hotkeyHint";
    /** 1 to 60 characters. */
    title: string;
    /** A line under the title, up to 200 characters. */
    detail?: string;
    /** The value before the owner changes it. A secret has none. */
    default?: any;
    /** For choice, up to 40. */
    options?: Array<string | { value: string; title?: string }>;
    /** For number. */
    min?: number;
    /** For number. */
    max?: number;
  }

  /**
   * A trigger in the manifest's activation list.
   * @since Atelier 1.0.0-beta.4
   */
  type Activation = "onStartup" | "onCommand" | "onWidgetVisible" | "onTileClick" | "onTimer" | "onCorner" | `onEvent:${keyof EventMap}`;

  /**
   * The manifest's contributes block.
   * @since Atelier 1.0.0-beta.4
   */
  interface Contributes {
    /** Board widgets. */
    widgets?: Array<{ id: string; title?: string; size?: WidgetSize; refresh?: number }>;
    /** Dock tiles. */
    tiles?: Array<{ id: string; title?: string; symbol?: string }>;
    /** Command palette entries. */
    commands?: Array<{ id: string; title: string; subtitle?: string; shortcut?: string }>;
    /** Hot corner actions. */
    cornerActions?: Array<{ id: string; title: string; symbol?: string }>;
    /** With onTimer: how often to wake it, 60 to 86400 seconds. */
    timer?: number;
  }

  /**
   * One series in a chart.
   * @since Atelier 1.0.0-beta.4
   */
  interface ChartSeries {
    /** Up to 40 characters. */
    label?: string;
    /** The last 120 are kept. */
    values: number[];
    /** Its colour. */
    color?: Color;
  }

  /** A row in a list view. */
  interface ListRow {
    /** The row's text. */
    title: string;
    /** Right-aligned, secondary. */
    detail?: string;
    /** An SF Symbol before the title. */
    symbol?: string;
    /** The symbol's colour. */
    color?: Color;
  }

  /**
   * Text. A plain string or number in a view is drawn as text too.
   * @example
   * atelier.ui.text("Hello", { size: 22, weight: "bold" })
   */
  interface TextView {
    type: "text";
    /** The text, cut at 400 characters. */
    text: string;
    /**
     * 8 to 64.
     * @default 13
     */
    size?: number;
    /**
     * Font weight.
     * @default "regular"
     */
    weight?: "light" | "regular" | "medium" | "semibold" | "bold" | "heavy";
    /**
     * Font design.
     * @default "default"
     */
    design?: "default" | "rounded" | "serif" | "mono";
    /** Defaults to primary. */
    color?: Color;
    /**
     * 1 to 8.
     * @default 2
     */
    lines?: number;
  }

  /**
   * An SF Symbol, with the text keys for its size and colour.
   * @example
   * atelier.ui.symbol("cloud.sun", { size: 28, color: "yellow" })
   */
  interface SymbolView {
    type: "symbol";
    /** An SF Symbol name, like timer. */
    name: string;
    /**
     * 8 to 64.
     * @default 18
     */
    size?: number;
    /** Symbol weight. */
    weight?: "light" | "regular" | "medium" | "semibold" | "bold" | "heavy";
    /** Defaults to primary. */
    color?: Color;
  }

  /**
   * A ring that fills from 0 to 1, with an optional label in the middle.
   * @example
   * atelier.ui.ring(0.42, { label: "42%", color: "accent" })
   */
  interface RingView {
    type: "ring";
    /** 0 to 1. */
    value: number;
    /** Drawn in the middle. */
    label?: string;
    /** Defaults to accent. */
    color?: Color;
    /**
     * Line width, 2 to 14.
     * @default 6
     */
    width?: number;
  }

  /**
   * A horizontal bar from 0 to 1.
   * @example
   * atelier.ui.bar(0.7, { label: "Disk" })
   */
  interface BarView {
    type: "bar";
    /** 0 to 1. */
    value: number;
    /** Drawn above the bar. */
    label?: string;
    /** Defaults to accent. */
    color?: Color;
  }

  /**
   * A small line chart of recent values.
   * @example
   * atelier.ui.sparkline([3, 5, 4, 8, 6], { color: "mint" })
   */
  interface SparklineView {
    type: "sparkline";
    /** The last 240 are kept. */
    values: number[];
    /** Defaults to accent. */
    color?: Color;
    /**
     * Fills under the line.
     * @default true
     */
    fill?: boolean;
  }

  /**
   * Up to 20 rows.
   * @example
   * atelier.ui.list([{ title: "Inbox", detail: "12", symbol: "tray" }, "Plain row"])
   */
  interface ListView {
    type: "list";
    /** Strings, or rows with title, detail, symbol and color. */
    items: Array<string | ListRow>;
  }

  /**
   * Children top to bottom. An array in a view is a vstack too.
   * @example
   * atelier.ui.vstack([atelier.ui.text("A"), atelier.ui.text("B")], { spacing: 4 })
   */
  interface VstackView {
    type: "vstack";
    /** The views inside. */
    children: View[];
    /**
     * 0 to 40.
     * @default 6
     */
    spacing?: number;
    /**
     * Alignment.
     * @default "leading"
     */
    align?: "leading" | "center" | "trailing" | "top" | "bottom";
    /**
     * Children that appear or disappear between renders animate this way.
     * @since Atelier 1.0.0-beta.4
     */
    transition?: "fade" | "slide" | "scale";
  }

  /**
   * Children side by side.
   * @example
   * atelier.ui.hstack([atelier.ui.symbol("bolt"), atelier.ui.text("Charging")])
   */
  interface HstackView {
    type: "hstack";
    /** The views inside. */
    children: View[];
    /**
     * 0 to 40.
     * @default 6
     */
    spacing?: number;
    /**
     * Alignment.
     * @default "center"
     */
    align?: "leading" | "center" | "trailing" | "top" | "bottom";
    /**
     * Children that appear or disappear between renders animate this way.
     * @since Atelier 1.0.0-beta.4
     */
    transition?: "fade" | "slide" | "scale";
  }

  /**
   * Children on top of each other.
   * @example
   * atelier.ui.zstack([atelier.ui.ring(0.5), atelier.ui.symbol("heart")], { align: "center" })
   */
  interface ZstackView {
    type: "zstack";
    /** The views inside, back to front. */
    children: View[];
    /**
     * Alignment.
     * @default "leading"
     */
    align?: "leading" | "center" | "trailing" | "top" | "bottom";
    /**
     * Children that appear or disappear between renders animate this way.
     * @since Atelier 1.0.0-beta.4
     */
    transition?: "fade" | "slide" | "scale";
  }

  /**
   * Flexible empty space.
   * @example
   * atelier.ui.spacer()
   */
  interface SpacerView {
    type: "spacer";
  }

  /**
   * A button. A tap runs its action once, under the usual 1-second limit.
   * @since Atelier 1.0.0-beta.4
   * @example
   * atelier.ui.button("Add", () => { count++; widget.refresh(); }, { symbol: "plus" })
   */
  interface ButtonView {
    type: "button";
    /** Its text. A title, a symbol or both. */
    title: string;
    /** A function, or an id registered with atelier.action. */
    action: Action;
    /** An SF Symbol. */
    symbol?: string;
    /**
     * How it looks.
     * @default "prominent"
     */
    style?: "prominent" | "plain";
  }

  /**
   * A switch. Its action receives { on } with the new state; redraw to show it.
   * @since Atelier 1.0.0-beta.4
   * @example
   * atelier.ui.toggle("Do not disturb", dnd, ({ on }) => { dnd = on; widget.refresh(); })
   */
  interface ToggleView {
    type: "toggle";
    /** Beside the switch. */
    label: string;
    /** Whether it is on. */
    on: boolean;
    /** Called with { on }. */
    action: Action;
  }

  /**
   * An image from the plugin folder (asset) or an https url on a host in network.hosts (needs network). The helper takes either and picks the key.
   * @since Atelier 1.0.0-beta.4
   * @example
   * atelier.ui.image(atelier.asset("cover.png"), { width: 64, height: 64, radius: 8 })
   */
  interface ImageView {
    type: "image";
    /** A png, jpg, jpeg, heic or pdf in the plugin folder, at most 2 MB. */
    asset?: string;
    /** An https image; Atelier fetches it with the rules of http.get. */
    url?: string;
    /** 4 to 600 points. */
    width?: number;
    /** 4 to 600 points. */
    height?: number;
    /**
     * How it fills its frame.
     * @default "fit"
     */
    fit?: "fit" | "fill";
    /**
     * Corner radius, 0 to 60.
     * @default 0
     */
    radius?: number;
  }

  /**
   * A bar, line or area chart. The helper takes values, or a list of series.
   * @since Atelier 1.0.0-beta.4
   * @example
   * atelier.ui.chart([12, 18, 9, 22], { kind: "bar", labels: ["M", "T", "W", "T"] })
   */
  interface ChartView {
    type: "chart";
    /**
     * Its form.
     * @default "bar"
     */
    kind?: "bar" | "line" | "area";
    /** One series; the last 120 are kept. */
    values?: number[];
    /** Up to 8 series instead of values. */
    series?: ChartSeries[];
    /** For values. */
    color?: Color;
    /** Along the x axis, up to 24 characters each. */
    labels?: string[];
    /** The top of the scale. */
    max?: number;
  }

  /**
   * Children in columns, row by row.
   * @since Atelier 1.0.0-beta.4
   * @example
   * atelier.ui.grid(stats.map((s) => atelier.ui.text(s)), { columns: 3 })
   */
  interface GridView {
    type: "grid";
    /** The views inside. */
    children: View[];
    /**
     * 1 to 6.
     * @default 2
     */
    columns?: number;
  }

  /**
   * A linear bar with its percentage.
   * @since Atelier 1.0.0-beta.4
   * @example
   * atelier.ui.progress(0.4, { label: "Upload" })
   */
  interface ProgressView {
    type: "progress";
    /** 0 to 1. */
    value: number;
    /** Drawn with it. */
    label?: string;
    /** Defaults to accent. */
    color?: Color;
  }

  /**
   * A thin line between views.
   * @since Atelier 1.0.0-beta.4
   * @example
   * atelier.ui.divider()
   */
  interface DividerView {
    type: "divider";
  }

  /** What a widget, panel or menu shows: a view object, a string or number (drawn as text), or an array (drawn as a vertical stack). Atelier draws it natively; a view never runs code. */
  type View = string | number | boolean | null | undefined | View[] |
    TextView | SymbolView | RingView | BarView | SparklineView | ListView | VstackView | HstackView | ZstackView | SpacerView | ButtonView | ToggleView | ImageView | ChartView | GridView | ProgressView | DividerView;

  /** Every event atelier.on can listen for, with its payload. */
  interface EventMap {
    /** Another app comes to the front. */
    appActivated: { name: string; bundleID: string };
    /** The active Space changes. */
    spaceChanged: {};
    /** Atelier changes the live or mesh wallpaper. A wallpaper picked in System Settings is not seen. */
    wallpaperChanged: { live?: string | null; mesh?: string | null };
    /** A theme or Look is applied, or reverted (id is null). */
    themeChanged: { id: string | null; name?: string };
    /** Every options.interval seconds, 5 to 86400, default 60. Up to 4 per plugin. date is ms since 1970. */
    timer: { date: number };
    /**
     * Once, after the plugin was updated, before any other handler runs.
     * @since Atelier 1.0.0-beta.4
     */
    update: { from: string; to: string };
    /**
     * The owner changed a setting. value is null for secrets; read them with settings.get.
     * @since Atelier 1.0.0-beta.4
     */
    settingsChanged: { key: string; value: any };
    /**
     * Another plugin sent a message with atelier.send.
     * @since Atelier 1.0.0-beta.4
     */
    message: { from: string; payload: any };
    /**
     * The Mac goes to sleep.
     * @since Atelier 1.0.0-beta.4
     */
    sleep: {};
    /**
     * The Mac wakes.
     * @since Atelier 1.0.0-beta.4
     */
    wake: {};
    /**
     * The screen locks.
     * @since Atelier 1.0.0-beta.4
     */
    screensLocked: {};
    /**
     * The screen unlocks.
     * @since Atelier 1.0.0-beta.4
     */
    screensUnlocked: {};
    /**
     * A display is added, removed or rearranged.
     * @since Atelier 1.0.0-beta.4
     */
    displaysChanged: { count: number };
    /**
     * The power source or battery level changes. level is 0 to 1, or null without a battery.
     * @since Atelier 1.0.0-beta.4
     */
    powerSource: { onBattery: boolean; level: number | null };
    /**
     * One of the plugin's panels called window.atelier.post(message).
     * @since Atelier 1.0.0-beta.4
     */
    panelMessage: { id: string; message: any };
  }

  /** The global, frozen atelier object: everything a plugin can do. There is no require, fetch, file system, process or DOM. */
  interface Api {
    /** The API version, currently "1.1". */
    readonly version: string;
    /**
     * Registers a widget for the board. Add it with the Plugin widget kind.
     * @param spec
     * @example
     * const w = atelier.widget({
     *   id: "hello",
     *   title: "Hello",
     *   refresh: 60,
     *   view: () => atelier.ui.text(new Date().toLocaleTimeString(), { size: 22, weight: "bold" }),
     * });
     */
    widget(spec: WidgetSpec): WidgetHandle;
    /**
     * Registers a tile for the Atelier Dock.
     * @param spec
     * @example
     * const tile = atelier.dockTile({ id: "timer", title: "Timer", symbol: "timer", text: "25:00", onClick: () => tile.update({ badge: 1 }) });
     */
    dockTile(spec: TileSpec): TileHandle;
    /**
     * Adds an entry to Atelier's Command palette.
     * @param spec
     * @returns The command's id.
     * @example
     * atelier.command({ title: "Say Hello", shortcut: "ctrl+opt+h", run: () => console.log("Hello!") });
     */
    command(spec: CommandSpec): string;
    /**
     * Adds an action you can put on a hot corner or edge in the Corners chapter.
     * @param spec
     * @returns The action's id.
     * @example
     * atelier.cornerAction({ title: "Shuffle Palette", symbol: "dice", run: shuffle });
     */
    cornerAction(spec: CornerActionSpec): string;
    /**
     * Listens for an event. See Events.
     * @param event
     * @param handler
     * @param [options]
     * @example
     * atelier.on("appActivated", ({ name }) => console.log(name + " is in front"));
     * atelier.on("timer", () => w.refresh(), { interval: 300 });
     */
    on<E extends keyof EventMap>(event: E, handler: (payload: EventMap[E]) => Awaitable<void>, options?: OnOptions): void;
    /**
     * Posts a notification. Titles are cut at 80 characters, bodies at 240.
     * Needs the `notifications` permission in the manifest, granted by the owner.
     * @param title
     * @param [body]
     * @example
     * atelier.notify("Focus session done", "Take five.");
     */
    notify(title: string, body?: string): void;
    /**
     * Posts a notification. Titles are cut at 80 characters, bodies at 240.
     * Needs the `notifications` permission in the manifest, granted by the owner.
     * @param spec
     * @example
     * atelier.notify("Focus session done", "Take five.");
     */
    notify(spec: NotifySpec): void;
    /**
     * Opens an https: or mailto: link in its default app, or an atelier://studio?chapter=… link.
     * Needs the `openURL` permission in the manifest, granted by the owner.
     * @param url
     * @example
     * atelier.openURL("https://github.com/notifications");
     */
    openURL(url: string): void;
    /**
     * Asks the owner for one line of text in a small Atelier window with your plugin's name on it. At most once every 10 seconds.
     * @param title
     * @param [options]
     * @returns The text, or null if the owner cancels.
     * @example
     * const token = await atelier.prompt("GitHub token", { secure: true, placeholder: "ghp_…" });
     */
    prompt(title: string, options?: PromptOptions): Promise<string | null>;
    /** A small key-value store of JSON values, private to the plugin and kept across launches. Keys are 1 to 128 characters; all values together at most 256 KB. */
    readonly storage: {
      /**
       * The value, or fallback (default null).
       * @param key
       * @param [fallback]
       * @example
       * let count = atelier.storage.get("count", 0);
       */
      get<T = any>(key: string, fallback?: T): T;
      /**
       * Stores any JSON value. null or undefined removes the key. Saved within a second and when the plugin stops.
       * @param key
       * @param value
       * @example
       * atelier.storage.set("count", count + 1);
       */
      set(key: string, value: any): void;
      /**
       * Removes the key.
       * @param key
       */
      remove(key: string): void;
      /** All keys, sorted. */
      keys(): string[];
    };
    /**
     * https requests to the hosts in the manifest's network.hosts. Every request is logged in the Console with its status and timing. The user agent is Atelier-Plugin/1.1 (<your id>).
     * Needs the `network` permission in the manifest, granted by the owner.
     */
    readonly http: {
      /**
       * Fetches a URL on a listed host.
       * Needs the `network` permission in the manifest, granted by the owner.
       * @param url
       * @param [options]
       * @returns Rejects on network failures, refused hosts and oversized responses.
       * @example
       * const r = await atelier.http.get("https://api.github.com/notifications", { headers: { Authorization: "Bearer " + token } });
       * if (r.ok) console.log(r.json().length);
       */
      get(url: string, options?: HttpOptions): Promise<HttpResponse>;
      /**
       * Sends a POST, with the same rules and limits as get. body is text; json is any JSON value, sent with Content-Type application/json unless you set one.
       * Needs the `network` permission in the manifest, granted by the owner.
       * @param url
       * @param [options]
       * @since Atelier 1.0.0-beta.4
       * @example
       * await atelier.http.post("https://api.example.com/items", { json: { title: "Hello" } });
       */
      post(url: string, options?: HttpSendOptions): Promise<HttpResponse>;
      /**
       * Sends a PUT, with the same rules and limits as get. body is text; json is any JSON value, sent with Content-Type application/json unless you set one.
       * Needs the `network` permission in the manifest, granted by the owner.
       * @param url
       * @param [options]
       * @since Atelier 1.0.0-beta.4
       */
      put(url: string, options?: HttpSendOptions): Promise<HttpResponse>;
      /**
       * Sends a PATCH, with the same rules and limits as get. body is text; json is any JSON value, sent with Content-Type application/json unless you set one.
       * Needs the `network` permission in the manifest, granted by the owner.
       * @param url
       * @param [options]
       * @since Atelier 1.0.0-beta.4
       */
      patch(url: string, options?: HttpSendOptions): Promise<HttpResponse>;
      /**
       * Sends a DELETE, with the same rules and limits as get. body is text; json is any JSON value, sent with Content-Type application/json unless you set one.
       * Needs the `network` permission in the manifest, granted by the owner.
       * @param url
       * @param [options]
       * @since Atelier 1.0.0-beta.4
       */
      delete(url: string, options?: HttpSendOptions): Promise<HttpResponse>;
    };
    /**
     * Changing Atelier's theme.
     * Needs the `appearance` permission in the manifest, granted by the owner.
     */
    readonly theme: {
      /**
       * Applies part of a theme. Validated like a theme and refused whole if anything is wrong. The first change from a plugin saves the owner's setup, so Revert in Looks undoes it.
       * Needs the `appearance` permission in the manifest, granted by the owner.
       * @param patch
       * @example
       * atelier.theme.apply({ colors: { accent: "#FF8A3D" }, wallpaper: { shader: "nebula", palette: "ember" } });
       */
      apply(patch: ThemePatch): void;
    };
    /** Helpers that build view objects. Each takes the view's main value and an optional style object with the view's other keys. See Views. */
    readonly ui: {
      /**
       * Builds a text view. Text. A plain string or number in a view is drawn as text too.
       * @param text The text, cut at 400 characters.
       * @param [style] The view's other keys.
       * @example
       * atelier.ui.text("Hello", { size: 22, weight: "bold" })
       */
      text(text: string | number, style?: Partial<Omit<TextView, "type" | "text">>): TextView;
      /**
       * Builds a symbol view. An SF Symbol, with the text keys for its size and colour.
       * @param name An SF Symbol name, like timer.
       * @param [style] The view's other keys.
       * @example
       * atelier.ui.symbol("cloud.sun", { size: 28, color: "yellow" })
       */
      symbol(name: string, style?: Partial<Omit<SymbolView, "type" | "name">>): SymbolView;
      /**
       * Builds a ring view. A ring that fills from 0 to 1, with an optional label in the middle.
       * @param value 0 to 1.
       * @param [style] The view's other keys.
       * @example
       * atelier.ui.ring(0.42, { label: "42%", color: "accent" })
       */
      ring(value: number, style?: Partial<Omit<RingView, "type" | "value">>): RingView;
      /**
       * Builds a bar view. A horizontal bar from 0 to 1.
       * @param value 0 to 1.
       * @param [style] The view's other keys.
       * @example
       * atelier.ui.bar(0.7, { label: "Disk" })
       */
      bar(value: number, style?: Partial<Omit<BarView, "type" | "value">>): BarView;
      /**
       * Builds a sparkline view. A small line chart of recent values.
       * @param values The last 240 are kept.
       * @param [style] The view's other keys.
       * @example
       * atelier.ui.sparkline([3, 5, 4, 8, 6], { color: "mint" })
       */
      sparkline(values: number[], style?: Partial<Omit<SparklineView, "type" | "values">>): SparklineView;
      /**
       * Builds a list view. Up to 20 rows.
       * @param items Strings, or rows with title, detail, symbol and color.
       * @example
       * atelier.ui.list([{ title: "Inbox", detail: "12", symbol: "tray" }, "Plain row"])
       */
      list(items: Array<string | ListRow>): ListView;
      /**
       * Builds a vstack view. Children top to bottom. An array in a view is a vstack too.
       * @param children The views inside.
       * @param [style] The view's other keys.
       * @example
       * atelier.ui.vstack([atelier.ui.text("A"), atelier.ui.text("B")], { spacing: 4 })
       */
      vstack(children: View[], style?: Partial<Omit<VstackView, "type" | "children">>): VstackView;
      /**
       * Builds a hstack view. Children side by side.
       * @param children The views inside.
       * @param [style] The view's other keys.
       * @example
       * atelier.ui.hstack([atelier.ui.symbol("bolt"), atelier.ui.text("Charging")])
       */
      hstack(children: View[], style?: Partial<Omit<HstackView, "type" | "children">>): HstackView;
      /**
       * Builds a zstack view. Children on top of each other.
       * @param children The views inside, back to front.
       * @param [style] The view's other keys.
       * @example
       * atelier.ui.zstack([atelier.ui.ring(0.5), atelier.ui.symbol("heart")], { align: "center" })
       */
      zstack(children: View[], style?: Partial<Omit<ZstackView, "type" | "children">>): ZstackView;
      /**
       * Builds a spacer view. Flexible empty space.
       * @example
       * atelier.ui.spacer()
       */
      spacer(): SpacerView;
      /**
       * Builds a button view. A button. A tap runs its action once, under the usual 1-second limit.
       * @param title Its text. A title, a symbol or both.
       * @param action A function, or an id registered with atelier.action.
       * @param [style] The view's other keys.
       * @since Atelier 1.0.0-beta.4
       * @example
       * atelier.ui.button("Add", () => { count++; widget.refresh(); }, { symbol: "plus" })
       */
      button(title: string, action: Action, style?: Partial<Omit<ButtonView, "type" | "title" | "action">>): ButtonView;
      /**
       * Builds a toggle view. A switch. Its action receives { on } with the new state; redraw to show it.
       * @param label Beside the switch.
       * @param on Whether it is on.
       * @param action Called with { on }.
       * @since Atelier 1.0.0-beta.4
       * @example
       * atelier.ui.toggle("Do not disturb", dnd, ({ on }) => { dnd = on; widget.refresh(); })
       */
      toggle(label: string, on: boolean, action: Action): ToggleView;
      /**
       * Builds a image view. An image from the plugin folder (asset) or an https url on a host in network.hosts (needs network). The helper takes either and picks the key.
       * @param source
       * @param [style] The view's other keys.
       * @since Atelier 1.0.0-beta.4
       * @example
       * atelier.ui.image(atelier.asset("cover.png"), { width: 64, height: 64, radius: 8 })
       */
      image(source: string, style?: Partial<Omit<ImageView, "type" | "source">>): ImageView;
      /**
       * Builds a chart view. A bar, line or area chart. The helper takes values, or a list of series.
       * @param data
       * @param [style] The view's other keys.
       * @since Atelier 1.0.0-beta.4
       * @example
       * atelier.ui.chart([12, 18, 9, 22], { kind: "bar", labels: ["M", "T", "W", "T"] })
       */
      chart(data: number[] | ChartSeries[], style?: Partial<Omit<ChartView, "type" | "data">>): ChartView;
      /**
       * Builds a grid view. Children in columns, row by row.
       * @param children The views inside.
       * @param [style] The view's other keys.
       * @since Atelier 1.0.0-beta.4
       * @example
       * atelier.ui.grid(stats.map((s) => atelier.ui.text(s)), { columns: 3 })
       */
      grid(children: View[], style?: Partial<Omit<GridView, "type" | "children">>): GridView;
      /**
       * Builds a progress view. A linear bar with its percentage.
       * @param value 0 to 1.
       * @param [style] The view's other keys.
       * @since Atelier 1.0.0-beta.4
       * @example
       * atelier.ui.progress(0.4, { label: "Upload" })
       */
      progress(value: number, style?: Partial<Omit<ProgressView, "type" | "value">>): ProgressView;
      /**
       * Builds a divider view. A thin line between views.
       * @since Atelier 1.0.0-beta.4
       * @example
       * atelier.ui.divider()
       */
      divider(): DividerView;
    };
    /**
     * Registers a named action for buttons and toggles. A view's action may also be a function; the prelude gives it an id per widget, replaced on every render. A tap calls it once; call widget.refresh() after to redraw.
     * @param id Letters, digits, - _ or ., up to 64.
     * @param handler Called with a toggle's { on }.
     * @returns The id, to use as a view's action.
     * @since Atelier 1.0.0-beta.4
     * @example
     * atelier.action("reset", () => { count = 0; widget.refresh(); });
     * atelier.ui.button("Reset", "reset", { style: "plain" })
     */
    action(id: string, handler: (payload?: any) => Awaitable<void>): string;
    /**
     * Checks that a png, jpg, jpeg, heic or pdf of at most 2 MB is in the plugin's own folder and returns its path, or throws. Use it for image views.
     * @param path Relative to the plugin folder.
     * @returns The same path, checked.
     * @since Atelier 1.0.0-beta.4
     * @example
     * atelier.ui.image(atelier.asset("images/logo.png"), { width: 48, height: 48, radius: 8 })
     */
    asset(path: string): string;
    /**
     * Localized text from the manifest's strings, in the owner's first preferred language the plugin has (pt-BR, then pt), then English, then the key itself. {name} is replaced from vars.
     * @param key
     * @param [vars]
     * @since Atelier 1.0.0-beta.4
     * @example
     * atelier.t("today", { n: 3 })
     */
    t(key: string, vars?: Record<string, string | number>): string;
    /**
     * The settings declared in the manifest. Values live in the plugin's storage under settings.<key> (storage.set refuses those keys); secrets live in the Keychain.
     * @since Atelier 1.0.0-beta.4
     */
    readonly settings: {
      /**
       * Reads a declared setting. Throws for a key the manifest does not declare.
       * @param key
       * @returns The value, or its default, or null.
       * @since Atelier 1.0.0-beta.4
       * @example
       * const minutes = atelier.settings.get("focus");
       */
      get(key: string): any;
      /**
       * Writes a declared setting, checked against its type; throws if it does not fit. null resets it to its default.
       * @param key
       * @param value
       * @since Atelier 1.0.0-beta.4
       */
      set(key: string, value: any): void;
      /**
       * Every declared setting's value, by key.
       * @since Atelier 1.0.0-beta.4
       */
      all(): Record<string, any>;
    };
    /**
     * Sends a message to another plugin. It arrives there as the message event only when this plugin lists it under messages.send, it lists this one under messages.receive, and it is on. Undelivered messages are noted in this plugin's Console.
     * @param to The other plugin's id.
     * @param payload Any JSON value, up to 64 KB.
     * @since Atelier 1.0.0-beta.4
     * @example
     * atelier.send("com.example.timer", { start: 25 });
     */
    send(to: string, payload: any): void;
    /**
     * Answers in Atelier's Command palette as the owner types. Each plugin's rows show in a section of their own. At most 4 per plugin.
     * @param spec
     * @returns The provider's id.
     * @since Atelier 1.0.0-beta.4
     * @example
     * atelier.paletteProvider({ id: "repos", title: "GitHub", prefix: "gh", search: async (q) =>
     *   (await myRepos()).filter((r) => r.name.includes(q)).map((r) => ({
     *     title: r.full_name, symbol: "book.closed", action: () => atelier.openURL(r.html_url) })) });
     */
    paletteProvider(spec: PaletteProviderSpec): string;
    /**
     * An item in the menu bar showing a symbol, a text or both; clicking it opens its menu. At most two per plugin.
     * Needs the `menuBar` permission in the manifest, granted by the owner.
     * @param spec
     * @since Atelier 1.0.0-beta.4
     * @example
     * const item = atelier.menuBarItem({ id: "focus", symbol: "timer", text: "25:00", menu: [
     *   { title: "Start", action: () => start() }, "separator", { title: "3 done today" }] });
     */
    menuBarItem(spec: MenuBarItemSpec): MenuBarHandle;
    /**
     * A stack the owner can put on the Atelier Dock (Stacks › From Plugins). Clicking it asks items and opens the usual stack bubble. At most 4 per plugin.
     * @param spec
     * @since Atelier 1.0.0-beta.4
     * @example
     * atelier.stackProvider({ id: "prs", title: "Pull Requests", symbol: "arrow.triangle.pull", refresh: 300,
     *   items: async () => prs.map((p) => ({ title: p.title, subtitle: p.repo, action: () => atelier.openURL(p.url) })) });
     */
    stackProvider(spec: StackProviderSpec): StackHandle;
    /**
     * A small live pill under the menu bar, drawn like Atelier's HUD. At most three show at once; a fourth is refused until one ends.
     * Needs the `liveActivities` permission in the manifest, granted by the owner.
     * @param spec
     * @since Atelier 1.0.0-beta.4
     * @example
     * const a = atelier.liveActivity({ id: "upload", title: "Uploading", symbol: "arrow.up", progress: 0 });
     * a.update({ progress: 0.5 });
     * a.end();
     */
    liveActivity(spec: LiveActivitySpec): LiveActivityHandle;
    /**
     * The owner's Scenes.
     * Needs the `scenes` permission in the manifest, granted by the owner.
     * @since Atelier 1.0.0-beta.4
     */
    readonly scenes: {
      /**
       * The owner's Scenes, by name.
       * Needs the `scenes` permission in the manifest, granted by the owner.
       * @since Atelier 1.0.0-beta.4
       */
      list(): Promise<Scene[]>;
      /**
       * Switches to that Scene, as choosing it in the Scenes chapter does. A snapshot is kept, so Snapshots can undo it.
       * Needs the `scenes` permission in the manifest, granted by the owner.
       * @param name
       * @since Atelier 1.0.0-beta.4
       * @example
       * const [first] = await atelier.scenes.list();
       * if (first) await atelier.scenes.apply(first.name);
       */
      apply(name: string): Promise<void>;
    };
    /**
     * A small floating window showing your HTML: no network, files from your folder only, no navigation or popups, nothing kept. At most 4 per plugin.
     * Needs the `panels` permission in the manifest, granted by the owner.
     * @param spec
     * @since Atelier 1.0.0-beta.4
     * @example
     * const p = atelier.panel({ id: "stats", title: "Stats", width: 360, height: 240,
     *   html: "<h1>Hi</h1><script>atelier.onMessage((m) => document.body.append(m.text))</script>" });
     * atelier.command({ title: "Show Stats", run: () => { p.show(); p.post({ text: "Hello" }); } });
     */
    panel(spec: PanelSpec): PanelHandle;
  }
}

/** Everything a plugin can do. See https://kaizensx.github.io/Atelier/make.html */
declare const atelier: Atelier.Api;

/**
 * Runs handler once after ms milliseconds. Up to 64 timers at once.
 * @param handler
 * @param [ms]
 * @param args
 */
declare function setTimeout(handler: (...args: any[]) => void, ms?: number, ...args: any[]): number;
/**
 * Runs handler every ms milliseconds, at least 1000.
 * @param handler
 * @param [ms]
 * @param args
 */
declare function setInterval(handler: (...args: any[]) => void, ms?: number, ...args: any[]): number;
/**
 * Cancels a timer.
 * @param id
 */
declare function clearTimeout(id: number | undefined): void;
/**
 * Cancels a timer.
 * @param id
 */
declare function clearInterval(id: number | undefined): void;

/** Writes to the Console in Mods › Library (and the Playground's console). Every error carries its line number. */
interface Console {
  log(...data: any[]): void;
  info(...data: any[]): void;
  warn(...data: any[]): void;
  error(...data: any[]): void;
  debug(...data: any[]): void;
}
declare var console: Console;
